class Solution {
public:
    int getXORSum(vector<int>& arr1, vector<int>& arr2) {
        int xor1 = 0, xor2 = 0;
        for (int x : arr1) xor1 ^= x;
        for (int y : arr2) xor2 ^= y;
        return xor1 & xor2;
    }
};

class Solution {
    public int getXORSum(int[] arr1, int[] arr2) {
        int xor1 = 0, xor2 = 0;
        for (int x : arr1) xor1 ^= x;
        for (int y : arr2) xor2 ^= y;
        return xor1 & xor2;
    }
}

/**
